{
  "name": "IT63XX系列多通道可编程直流电源",
  "name_en": "IT63XX Series Multi-Channel Programmable DC Power Supply",
  "manufacturer": "ITECH",
  "description": "一款多通道可编程直流电源，可为电子电路、器件或原型系统提供可调直流电压与电流输出，并支持分通道开关与输出测量，常用于实验室台式供电、电路调试、性能测试和器件表征。",
  "description_en": "A multi-channel programmable DC power supply that provides adjustable DC voltage and current output for electronic circuits, devices, and prototypes. It supports per-channel output control and output measurement, and is commonly used for bench power, circuit debugging, performance testing, and device characterization in laboratories.",
  "actions": [
    {
      "action_name": "auto-channel_on",
      "description": "打开指定通道输出",
      "description_en": "Enable output on the specified channel"
    },
    {
      "action_name": "auto-channel_off",
      "description": "关闭指定通道输出",
      "description_en": "Disable output on the specified channel"
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置指定通道输出电压",
      "description_en": "Set the output voltage of the specified channel"
    },
    {
      "action_name": "auto-set_current",
      "description": "设置指定通道输出电流",
      "description_en": "Set the output current of the specified channel"
    },
    {
      "action_name": "auto-meas_voltage",
      "description": "测量指定通道输出电压",
      "description_en": "Measure the output voltage of the specified channel"
    },
    {
      "action_name": "auto-meas_current",
      "description": "测量指定通道输出电流",
      "description_en": "Measure the output current of the specified channel"
    },
    {
      "action_name": "auto-beep",
      "description": "触发设备蜂鸣器",
      "description_en": "Trigger the device beeper"
    }
  ],
  "tag_hints": [
    "programmable DC power supply",
    "multi-channel output",
    "bench power supply",
    "voltage/current sourcing",
    "electrical testing",
    "device characterization"
  ]
}

